"""Deterministic renderer and diff generator for Yoda component configs."""

from __future__ import annotations

import difflib
from pathlib import Path

import yaml

from .schema import ReleaseBOM, YodaConfig


def _bool_str(val: bool) -> str:
    return "true" if val else "false"


def render_flask_cfg(cfg: YodaConfig, yoda_commit: str = "unknown") -> str:
    """Render portal/flask.cfg matching roles/yoda_portal/templates/flask.cfg.j2."""
    lines = [
        "# Generated by yoda-config. Do not edit manually.",
        "import ssl",
        "from flask import current_app as app",
        "",
        "# General Flask configuration",
        f"SECRET_KEY          = {cfg.portal.secret_key!r}",
        f"PORTAL_TITLE_TEXT   = {cfg.portal.title!r}",
        f"YODA_VERSION        = {cfg.instance.yoda_version!r}",
        f"YODA_ENVIRONMENT    = {cfg.instance.environment!r}",
        f"YODA_COMMIT         = {yoda_commit!r}",
        f"RESEARCH_ENABLED    = {cfg.modules.research_enabled!r}",
        f"OPEN_SEARCH_ENABLED = {cfg.modules.opensearch.enabled!r}",
        f"DEPOSIT_ENABLED     = {cfg.modules.deposit_enabled!r}",
        f"DATAREQUEST_ENABLED = {cfg.modules.datarequest.enabled!r}",
        f"TOKENS_ENABLED      = {cfg.modules.tokens.enabled!r}",
        f"TOKEN_LIFETIME      = {cfg.modules.tokens.lifetime_hours}",
        f"SRAM_ENABLED        = {cfg.auth.sram.enabled!r}",
        f"CACHING_ENABLED     = {cfg.portal.caching_enabled!r}",
        "",
        "# Logging configuration",
        f"LOG_API_CALL_DURATION = {cfg.portal.log_api_call_duration!r}",
        "",
        "# Flask-Session configuration",
        "SESSION_TYPE               = 'filesystem'",
        "SESSION_COOKIE_NAME        = '__Host-session'",
        "SESSION_COOKIE_HTTPONLY    = True",
        "SESSION_COOKIE_SECURE      = True",
        f"SESSION_COOKIE_SAMESITE    = {cfg.portal.session_cookie_samesite!r}",
        f"PERMANENT_SESSION_LIFETIME = {cfg.portal.permanent_session_lifetime}",
        "SESSION_USE_SIGNER         = True",
        f"SESSION_FILE_DIR           = {cfg.portal.session_file_dir!r}",
        "",
        "# iRODS authentication configuration",
        f"IRODS_ICAT_HOSTNAME = {cfg.irods.icat_fqdn!r}",
        f"IRODS_ICAT_PORT     = {str(cfg.irods.icat_port)!r}",
        f"IRODS_DEFAULT_ZONE  = {cfg.irods.zone!r}",
        f"IRODS_DEFAULT_RESC  = {cfg.irods.default_resource!r}",
        f"IRODS_SSL_CA_FILE   = {cfg.irods.ca_certificate_file!r}",
        f"IRODS_AUTH_SCHEME   = {cfg.irods.authentication_scheme!r}",
        "IRODS_CLIENT_OPTIONS_FOR_SSL = {",
        '    "irods_client_server_policy": "CS_NEG_REQUIRE",',
        '    "irods_client_server_negotiation": "request_server_negotiation",',
        '    "irods_ssl_ca_certificate_file": IRODS_SSL_CA_FILE,',
        f'    "irods_ssl_verify_server": "{cfg.irods.ssl_verify_server}",',
        '    "irods_encryption_key_size": 16,',
        '    "irods_encryption_salt_size": 8,',
        '    "irods_encryption_num_hash_rounds": 16,',
        '    "irods_encryption_algorithm": "AES-256-CBC",',
        "}",
        "IRODS_SESSION_OPTIONS = {",
        "    'ssl_context': ssl.create_default_context(",
        "        purpose=ssl.Purpose.SERVER_AUTH,",
        "        cafile=IRODS_SSL_CA_FILE,",
        "    ),",
        "    **IRODS_CLIENT_OPTIONS_FOR_SSL,",
        "    'authentication_scheme': IRODS_AUTH_SCHEME,",
        "    'application_name': 'yoda-portal',",
        "}",
        "",
    ]

    if cfg.auth.oidc.enabled:
        oidc = cfg.auth.oidc
        cb = f"https://{cfg.endpoints.portal_fqdn}/user/callback"
        auth_uri = (
            f"{oidc.auth_base_uri}?response_type=code&client_id={oidc.client_id}"
            f"&redirect_uri={cb}&scope={oidc.scopes}&acr_values={oidc.acr_values}"
        )
        lines.extend(
            [
                "# OIDC configuration",
                "OIDC_ENABLED         = True",
                f"OIDC_DOMAINS         = {oidc.domains!r}",
                f"OIDC_ALWAYS_REDIRECT = {oidc.always_redirect!r}",
                f"OIDC_CLIENT_ID       = {oidc.client_id!r}",
                f"OIDC_CLIENT_SECRET   = {oidc.client_secret!r}",
                f"OIDC_CALLBACK_URI    = {cb!r}",
                f"OIDC_AUTH_BASE_URI   = {oidc.auth_base_uri!r}",
                f"OIDC_AUTH_URI        = {auth_uri!r}",
                f"OIDC_LOGIN_HINT      = {oidc.login_hint!r}",
                f"OIDC_TOKEN_URI       = {oidc.token_uri!r}",
                f"OIDC_SCOPES          = {oidc.scopes!r}",
                f"OIDC_ACR_VALUES      = {oidc.acr_values!r}",
                f"OIDC_USERINFO_URI    = {oidc.userinfo_uri!r}",
                f"OIDC_EMAIL_FIELD     = {oidc.email_field!r}",
                f"OIDC_JWKS_URI        = {oidc.jwks_uri!r}",
                f"OIDC_JWT_ISSUER      = {oidc.jwt_issuer!r}",
                "OIDC_JWT_OPTIONS     = {",
                f'    "require_exp": {oidc.req_exp!r},',
                f'    "require_iat": {oidc.req_iat!r},',
                f'    "require_nbf": {oidc.req_nbf!r},',
                f'    "verify_aud": {oidc.verify_aud!r},',
                f'    "verify_iat": {oidc.verify_iat!r},',
                f'    "verify_exp": {oidc.verify_exp!r},',
                f'    "verify_iss": {oidc.verify_iss!r},',
                '    "verify_signature": True,',
                "}",
                "",
            ]
        )

    lines.extend(
        [
            "# Portal theme & paths",
            "YODA_PORTAL_PATH = '/var/www/yoda'",
            "YODA_CONFIG_PATH = '/var/www/yoda/config'",
            f"YODA_THEME_PATH = {cfg.customizations.theme_path!r}",
            f"YODA_THEME = {cfg.customizations.theme!r}",
            f"YODA_THEME_MAPPING = {cfg.customizations.theme_mapping!r}",
            f"YODA_EUS_FQDN = {(cfg.endpoints.eus_fqdn or '')!r}",
            f"DATAREQUEST_HELP_CONTACT_NAME  = {cfg.modules.datarequest.help_contact_name!r}",
            f"DATAREQUEST_HELP_CONTACT_EMAIL = {cfg.modules.datarequest.help_contact_email!r}",
            f"UPLOAD_PART_FILES = {cfg.portal.upload_part_files!r}",
            f"TEXT_FILE_EXTENSIONS = {cfg.portal.text_file_extensions!r}",
            f"MONITOR_OUTPUT_DIR = {cfg.portal.monitor_output_dir!r}",
            f"MONITOR_SIGNAL_FILE = {cfg.portal.monitor_signal_file!r}",
            "",
        ]
    )
    return "\n".join(lines)


def render_rules_uu_cfg(cfg: YodaConfig) -> str:
    """Render icat/rules_uu.cfg matching roles/yoda_rulesets/templates/rules_uu.cfg.j2."""
    lines = [
        "# Generated by yoda-config. Do not edit manually.",
        f"environment                    = '{cfg.instance.environment}'",
        f"default_yoda_schema            = '{cfg.customizations.default_schema}'",
        "",
        f"resource_primary               = '{cfg.irods.default_resource}'",
        f"resource_replica               = '{' '.join(cfg.irods.replica_resources)}'",
        f"resource_research              = '{cfg.irods.research_resource}'",
        f"resource_vault                 = '{cfg.irods.vault_resource}'",
        f"resource_trigger_pol           = '{' '.join(cfg.irods.trigger_policy_resources)}'",
        f"resource_repl_exempt           = '{' '.join(cfg.irods.replication_exempt_resources)}'",
        f"enable_nfs_resource            = '{_bool_str(cfg.irods.enable_nfs_resource)}'",
        "",
        f"notifications_enabled          = '{_bool_str(cfg.integrations.smtp.notifications_enabled)}'",
        f"notifications_sender_email     = '{cfg.integrations.smtp.sender_email}'",
        f"notifications_sender_name      = '{cfg.integrations.smtp.sender_name}'",
        f"notifications_reply_to         = '{cfg.integrations.smtp.reply_to}'",
        "",
        f"smtp_server                    = '{cfg.integrations.smtp.server}'",
        f"smtp_username                  = '{cfg.integrations.smtp.username}'",
        f"smtp_password                  = '{cfg.integrations.smtp.password}'",
        f"smtp_auth                      = '{_bool_str(cfg.integrations.smtp.auth)}'",
        f"smtp_starttls                  = '{_bool_str(cfg.integrations.smtp.starttls)}'",
        "",
        f"datacite_rest_api_url          = 'https://{cfg.integrations.datacite.rest_api_url}'",
        f"datacite_username              = '{cfg.integrations.datacite.username}'",
        f"datacite_password              = '{cfg.integrations.datacite.password}'",
        f"datacite_publisher             = '{cfg.integrations.datacite.publisher}'",
        f"datacite_tls_verify            = '{_bool_str(cfg.integrations.datacite.tls_verify)}'",
        "",
        f"eus_api_fqdn                   = '{cfg.endpoints.eus_api_fqdn or ''}'",
        f"eus_api_port                   = '{cfg.endpoints.eus_api_port}'",
        f"eus_api_secret                 = '{cfg.integrations.eus.api_secret}'",
        f"eus_api_tls_verify             = '{_bool_str(cfg.endpoints.eus_api_tls_verify)}'",
        "",
        f"enable_deposit                 = '{_bool_str(cfg.modules.deposit_enabled)}'",
        f"enable_open_search             = '{_bool_str(cfg.modules.opensearch.enabled)}'",
        f"enable_datarequest             = '{_bool_str(cfg.modules.datarequest.enabled)}'",
        f"yoda_portal_fqdn               = '{cfg.endpoints.portal_fqdn}'",
        f"enable_data_package_reference  = '{_bool_str(cfg.modules.data_package_reference_enabled)}'",
        "",
        f"epic_pid_enabled               = '{_bool_str(cfg.integrations.epic.enabled)}'",
    ]

    if cfg.integrations.epic.enabled:
        lines.extend(
            [
                f"epic_url                       = '{cfg.integrations.epic.url}'",
                f"epic_handle_prefix             = '{cfg.integrations.epic.handle_prefix}'",
                f"epic_key                       = '{cfg.integrations.epic.credentials_store}/epic_key.pem'",
                f"epic_certificate               = '{cfg.integrations.epic.credentials_store}/epic_cert.pem'",
            ]
        )

    lines.append(f"enable_tokens                  = '{_bool_str(cfg.modules.tokens.enabled)}'")
    if cfg.modules.tokens.enabled:
        lines.extend(
            [
                f"token_database                 = '{cfg.modules.tokens.database_path}'",
                f"token_database_password        = '{cfg.modules.tokens.database_password}'",
                f"token_length                   = '{cfg.modules.tokens.length}'",
                f"token_lifetime                 = '{cfg.modules.tokens.lifetime_hours}'",
                f"token_expiration_notification  = '{cfg.modules.tokens.expiration_notification_hours}'",
            ]
        )

    lines.extend(
        [
            "",
            f"enable_async_checksum          = '{_bool_str(cfg.modules.async_checksum_enabled)}'",
            f"async_checksum_delay_time      = '{cfg.modules.async_checksum_delay_time}'",
            f"async_replication_delay_time   = '{cfg.modules.async_replication_delay_time}'",
            f"async_replication_max_rss      = '{cfg.modules.async_replication_max_rss}'",
            f"async_revision_delay_time      = '{cfg.modules.async_revision_delay_time}'",
            f"async_revision_max_rss         = '{cfg.modules.async_revision_max_rss}'",
            f"vault_copy_backoff_time        = '{cfg.modules.vault_copy_backoff_time}'",
            f"vault_copy_max_retries         = '{cfg.modules.vault_copy_max_retries}'",
            f"vault_copy_multithread_enabled = '{_bool_str(cfg.modules.vault_copy_multithread_enabled)}'",
            f"deaccession_cooldown           = '{cfg.modules.deaccession_cooldown_days}'",
            f"enable_inactivity_notification = '{_bool_str(cfg.modules.inactivity_notification_enabled)}'",
        ]
    )

    if cfg.modules.inactivity_notification_enabled:
        lines.append(f"inactivity_cutoff_months       = '{cfg.modules.inactivity_cutoff_months}'")

    lines.append(f"enable_data_package_archive    = '{_bool_str(cfg.modules.archive.enabled)}'")
    if cfg.modules.archive.enabled:
        lines.extend(
            [
                f"data_package_archive_fqdn      = '{cfg.modules.archive.fqdn}'",
                f"data_package_archive_minimum   = '{cfg.modules.archive.minimum_bytes}'",
                f"data_package_archive_maximum   = '{cfg.modules.archive.maximum_bytes}'",
                f"data_package_archive_resource  = '{cfg.modules.archive.resource}'",
            ]
        )

    lines.append(f"temporary_files                = '{' '.join(cfg.modules.temporary_files)}'")

    if cfg.auth.external_users_enabled:
        domain_filter = cfg.auth.external_users_domain_filter.replace(" ", "").replace("|", " ")
        lines.append(f"external_users_domain_filter   = '{domain_filter}'")

    lines.append(f"enable_sram                    = '{_bool_str(cfg.auth.sram.enabled)}'")
    if cfg.auth.sram.enabled:
        lines.extend(
            [
                f"sram_rest_api_url              = 'https://{cfg.auth.sram.rest_api_url}'",
                f"sram_api_key                   = '{cfg.auth.sram.api_key}'",
                f"sram_service_entity_id         = '{cfg.auth.sram.service_entity_id}'",
                f"sram_verbose_logging           = '{_bool_str(cfg.auth.sram.verbose_logging)}'",
                f"sram_tls_verify                = '{_bool_str(cfg.auth.sram.tls_verify)}'",
                f"sram_co_default_label          = '{cfg.auth.sram.co_default_label}'",
                f"sram_co_logo                   = '{cfg.auth.sram.co_logo}'",
                f"sram_co_default_admins         = '{' '.join(cfg.auth.sram.co_default_admins)}'",
                f"sram_external_users_co         = '{cfg.auth.sram.external_users_co}'",
            ]
        )

    lines.extend(
        [
            "",
            f"arb_enabled                    = '{_bool_str(cfg.irods.arb_enabled)}'",
            f"arb_exempt_resources           = '{' '.join(cfg.irods.arb_exempt_resources)}'",
            f"arb_min_gb_free                = '{cfg.irods.arb_min_gb_free}'",
            f"arb_min_percent_free           = '{cfg.irods.arb_min_percent_free}'",
            f"remote_anonymous_access        = '{' '.join(cfg.irods.anonymous_permit_addresses)}'",
            f"user_max_connections_enabled   = '{_bool_str(cfg.irods.user_max_connections_enabled)}'",
            f"user_max_connections_number    = '{cfg.irods.user_max_connections_number}'",
            f"measure_coverage               = '{_bool_str(cfg.modules.measure_coverage)}'",
            f"text_file_extensions           = '{' '.join(cfg.portal.text_file_extensions)}'",
            f"pregenerated_data_dir          = '{cfg.modules.pregenerated_data_dir}'",
            f"matomo_tracking_enabled        = '{_bool_str(cfg.integrations.matomo.tracking_enabled)}'",
            f"matomo_counter_enabled         = '{_bool_str(cfg.integrations.matomo.counter_enabled)}'",
            f"matomo_server_fqdn             = '{cfg.integrations.matomo.server_fqdn}'",
            f"matomo_site_id                 = '{cfg.integrations.matomo.site_id}'",
            "",
        ]
    )
    return "\n".join(lines)


