def render_moai_settings_ini(cfg: YodaConfig) -> str:
    """Render public/moai-settings.ini matching roles/yoda_moai/templates/moai-settings.ini.j2."""
    admin_email = cfg.integrations.smtp.reply_to or cfg.integrations.smtp.sender_email or "yoda@example.org"
    lines = [
        "# Generated by yoda-config. Do not edit manually.",
        "[composite:main]",
        "use = egg:Paste#urlmap",
        "/oai = yoda_moai",
        "",
        "[app:yoda_moai]",
        "use = egg:moai",
        "name = Yoda MOAI Feed",
        f"url = https://{cfg.endpoints.public_fqdn}/oai/oai",
        f"admin_email = {admin_email}",
        "formats = oai_dc datacite oai_datacite iso19139",
        "disallow_sets = private",
        "database = sqlite+pysqlite3:////var/www/moai/moai.db",
        "provider = file:///var/www/moai/metadata",
        "content = moai_yoda",
        "forcedflush = 10000",
        "",
        "[server:main]",
        "use = egg:PasteScript#wsgiutils",
        "host = 0.0.0.0",
        "port = 8080",
        "",
    ]
    return "\n".join(lines)


def render_davrods_vhost_conf(cfg: YodaConfig) -> str:
    """Render davrods/davrods-vhost.conf for internal port 8080 behind external TLS ingress."""
    auth_scheme = "PAM" if cfg.irods.authentication_scheme == "pam_password" else "Native"
    lines = [
        "# Generated by yoda-config. Do not edit manually.",
        "# Runs behind external TLS ingress on internal port 8080.",
        "Listen 8080",
        "",
        "<VirtualHost *:8080>",
        f"    ServerName {cfg.endpoints.davrods_fqdn}",
        "    <Location />",
        "        DirectoryIndex disabled",
        "        AuthType Basic",
        "        AuthName DAV",
        "        AuthBasicProvider irods",
        "        Require valid-user",
        "        Dav davrods-locallock",
        "        DavRodsEnvFile /etc/apache2/irods/irods_environment.json",
        f"        DavRodsServer {cfg.irods.icat_fqdn} {cfg.irods.icat_port}",
        f"        DavRodsZone {cfg.irods.zone}",
        f"        DavRodsAuthScheme {auth_scheme}",
        "        DavRodsAuthTTLHours 1",
        "        DavRodsAnonymousMode Off",
        "    </Location>",
        "</VirtualHost>",
    ]

    if cfg.endpoints.davrods_anonymous_enabled and cfg.endpoints.davrods_anonymous_fqdn:
        lines.extend(
            [
                "",
                "<VirtualHost *:8080>",
                f"    ServerName {cfg.endpoints.davrods_anonymous_fqdn}",
                "    <Location />",
                "        DirectoryIndex disabled",
                "        Require all granted",
                "        Dav davrods-nolocks",
                "        DavRodsEnvFile /etc/apache2/irods/irods_environment.json",
                f"        DavRodsServer {cfg.irods.icat_fqdn} {cfg.irods.icat_port}",
                f"        DavRodsZone {cfg.irods.zone}",
                "        DavRodsAuthScheme Native",
                "        DavRodsAnonymousMode On",
                "        DavRodsAnonymousLogin anonymous \"\"",
                "    </Location>",
                "</VirtualHost>",
            ]
        )

    lines.append("")
    return "\n".join(lines)


def _web_network_name(cfg: YodaConfig) -> str:
    return f"yoda-web-{cfg.instance.name}"


def render_web_tier_compose(cfg: YodaConfig, bom: ReleaseBOM) -> str:
    """Render a production-oriented Compose manifest for the stateless web tier (Option C)."""
    net_name = _web_network_name(cfg)
    services: dict[str, object] = {
        "portal": {
            "image": bom.web_tier_images["portal"].full_ref,
            "restart": "unless-stopped",
            "networks": ["yoda-web"],
            "environment": {
                "YODA_ENVIRONMENT": cfg.instance.environment,
                "YODA_PORTAL_FQDN": cfg.endpoints.portal_fqdn,
                "IRODS_ICAT_FQDN": cfg.irods.icat_fqdn,
            },
            "volumes": [
                "../portal/flask.cfg:/etc/yoda/flask.cfg:ro",
                f"{cfg.customizations.theme_path}:/var/www/yoda/themes:ro",
            ],
            "healthcheck": {
                "test": ["CMD", "curl", "-fsS", "http://127.0.0.1:8080/"],
                "interval": "30s",
                "timeout": "5s",
                "retries": 3,
            },
        },
        "davrods": {
            "image": bom.web_tier_images["davrods"].full_ref,
            "restart": "unless-stopped",
            "networks": ["yoda-web"],
            "environment": {
                "YODA_DAVRODS_FQDN": cfg.endpoints.davrods_fqdn,
                "IRODS_ICAT_FQDN": cfg.irods.icat_fqdn,
                "IRODS_ZONE": cfg.irods.zone,
            },
            "volumes": [
                "../davrods/davrods-vhost.conf:/etc/yoda/davrods-vhost.conf:ro",
            ],
        },
        "public": {
            "image": bom.web_tier_images["public"].full_ref,
            "restart": "unless-stopped",
            "networks": ["yoda-web"],
            "environment": {
                "YODA_PUBLIC_FQDN": cfg.endpoints.public_fqdn,
            },
            "volumes": [
                "../public/moai-settings.ini:/etc/yoda/moai-settings.ini:ro",
            ],
        },
    }

    if cfg.integrations.eus.enabled and "eus" in bom.web_tier_images:
        services["eus"] = {
            "image": bom.web_tier_images["eus"].full_ref,
            "restart": "unless-stopped",
            "networks": ["yoda-web"],
            "environment": {
                "YODA_EUS_FQDN": cfg.endpoints.eus_fqdn,
                "YODA_DB_HOST": cfg.database.host,
                "YODA_DB_PORT": str(cfg.database.port),
            },
            "volumes": [
                "../eus/eus.cfg:/etc/yoda/eus.cfg:ro",
            ],
        }

    doc = {
        "name": f"yoda-web-{cfg.instance.name}",
        "networks": {
            "yoda-web": {
                "name": net_name,
            }
        },
        "services": services,
    }
    return "# Generated by yoda-config from Release BOM. Do not edit manually.\n" + yaml.safe_dump(
        doc, sort_keys=False
    )


def render_edge_caddyfile(cfg: YodaConfig) -> str:
    """Render a reference Caddy reverse-proxy config for TLS termination and routing."""
    anubis = cfg.integrations.anubis.enabled
    public_upstream = "anubis-public:8923" if anubis else "public:8080"
    anon_dav_upstream = "anubis-davrods:8924" if anubis else "davrods:8080"

    blocks = [
        "# Generated by yoda-config (--with-reference-edge). Do not edit manually.",
        "# Terminates TLS and forwards Host, X-Forwarded-For, and X-Forwarded-Proto to Yoda web-tier containers.",
        "",
        f"{cfg.endpoints.portal_fqdn} {{",
        "    reverse_proxy portal:8080",
        "}",
        "",
        f"{cfg.endpoints.davrods_fqdn} {{",
        "    reverse_proxy davrods:8080",
        "}",
        "",
        f"{cfg.endpoints.public_fqdn} {{",
        f"    reverse_proxy {public_upstream}",
        "}",
    ]

    if cfg.endpoints.davrods_anonymous_enabled and cfg.endpoints.davrods_anonymous_fqdn:
        blocks.extend(
            [
                "",
                f"{cfg.endpoints.davrods_anonymous_fqdn} {{",
                f"    reverse_proxy {anon_dav_upstream}",
                "}",
            ]
        )

    if cfg.integrations.eus.enabled and cfg.endpoints.eus_fqdn:
        blocks.extend(
            [
                "",
                f"{cfg.endpoints.eus_fqdn} {{",
                "    reverse_proxy eus:8080",
                "}",
            ]
        )

    blocks.append("")
    return "\n".join(blocks)


def render_edge_compose(cfg: YodaConfig) -> str:
    """Render an optional reference edge Compose stack (TLS proxy + Anubis/Redis when enabled)."""
    net_name = _web_network_name(cfg)
    depends_on: list[str] = []
    services: dict[str, object] = {}

    if cfg.integrations.anubis.enabled:
        services["anubis-redis"] = {
            "image": "redis:7-alpine",
            "restart": "unless-stopped",
            "networks": ["yoda-web"],
            "command": ["redis-server", "--requirepass", "${ANUBIS_REDIS_PASSWORD}"],
        }
        services["anubis-public"] = {
            "image": "ghcr.io/techarohq/anubis:latest",
            "restart": "unless-stopped",
            "networks": ["yoda-web"],
            "depends_on": ["anubis-redis"],
            "environment": {
                "BIND": ":8923",
                "TARGET": "http://public:8080",
                "STORAGE_BACKEND": "valkey",
                "VALKEY_URI": "redis://:${ANUBIS_REDIS_PASSWORD}@anubis-redis:6379/0",
                "ED25519_PRIVATE_KEY_HEX": "${ANUBIS_ED25519_PRIVATE_KEY}",
            },
        }
        depends_on.append("anubis-public")

        if cfg.endpoints.davrods_anonymous_enabled and cfg.endpoints.davrods_anonymous_fqdn:
            services["anubis-davrods"] = {
                "image": "ghcr.io/techarohq/anubis:latest",
                "restart": "unless-stopped",
                "networks": ["yoda-web"],
                "depends_on": ["anubis-redis"],
                "environment": {
                    "BIND": ":8924",
                    "TARGET": "http://davrods:8080",
                    "STORAGE_BACKEND": "valkey",
                    "VALKEY_URI": "redis://:${ANUBIS_REDIS_PASSWORD}@anubis-redis:6379/0",
                    "ED25519_PRIVATE_KEY_HEX": "${ANUBIS_ED25519_PRIVATE_KEY}",
                },
            }
            depends_on.append("anubis-davrods")

    edge_proxy: dict[str, object] = {
        "image": "caddy:2-alpine",
        "restart": "unless-stopped",
        "networks": ["yoda-web"],
        "ports": ["80:80", "443:443"],
        "volumes": [
            "./Caddyfile:/etc/caddy/Caddyfile:ro",
            "caddy_data:/data",
            "caddy_config:/config",
        ],
    }
    if depends_on:
        edge_proxy["depends_on"] = depends_on

    ordered_services: dict[str, object] = {"edge-proxy": edge_proxy, **services}
    doc = {
        "name": f"yoda-edge-{cfg.instance.name}",
        "networks": {
            "yoda-web": {
                "name": net_name,
                "external": True,
            }
        },
        "volumes": {"caddy_data": {}, "caddy_config": {}},
        "services": ordered_services,
    }
    return (
        "# Generated by yoda-config (--with-reference-edge). Do not edit manually.\n"
        + yaml.safe_dump(doc, sort_keys=False)
    )


def render_all(
    cfg: YodaConfig,
    bom: ReleaseBOM | None = None,
    with_reference_edge: bool = False,
) -> dict[str, str]:
    """Render all component configuration artifacts as a relative-path -> content mapping."""
    artifacts: dict[str, str] = {
        "portal/flask.cfg": render_flask_cfg(cfg),
        "icat/rules_uu.cfg": render_rules_uu_cfg(cfg),
        "public/moai-settings.ini": render_moai_settings_ini(cfg),
        "davrods/davrods-vhost.conf": render_davrods_vhost_conf(cfg),
    }
    if cfg.integrations.eus.enabled:
        artifacts["eus/eus.cfg"] = render_eus_cfg(cfg)
    if bom is not None:
        artifacts["web-tier/docker-compose.yml"] = render_web_tier_compose(cfg, bom)
    if with_reference_edge:
        artifacts["edge/Caddyfile"] = render_edge_caddyfile(cfg)
        artifacts["edge/docker-compose.edge.yml"] = render_edge_compose(cfg)
    return artifacts


def write_rendered(artifacts: dict[str, str], out_dir: str | Path) -> list[Path]:
    """Write rendered artifacts to disk and return written paths."""
    base = Path(out_dir)
    written: list[Path] = []
    for rel_path, content in artifacts.items():
        target = base / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        written.append(target)
    return written


def diff_rendered(artifacts: dict[str, str], target_dir: str | Path) -> str:
    """Return a unified diff between rendered artifacts and files currently in target_dir."""
    base = Path(target_dir)
    diffs: list[str] = []
    for rel_path, new_content in artifacts.items():
        existing_file = base / rel_path
        old_lines = (
            existing_file.read_text(encoding="utf-8").splitlines(keepends=True)
            if existing_file.is_file()
            else []
        )
        new_lines = new_content.splitlines(keepends=True)
        diff = list(
            difflib.unified_diff(
                old_lines,
                new_lines,
                fromfile=f"current/{rel_path}",
                tofile=f"desired/{rel_path}",
            )
        )
        if diff:
            diffs.append("".join(diff))
    return "\n".join(diffs)
